    def normalize_conversion_mode(conversion_mode: str) -> ConversionMode:
        normalized = str(conversion_mode or DEFAULT_PARTITION_CONVERSION_MODE).strip().lower()
        if normalized not in PARTITION_CONVERSION_MODES:
            raise ValueError(
                f"Unsupported partition_conversion_mode {conversion_mode!r}. "
                f"Expected one of {sorted(PARTITION_CONVERSION_MODES)}."
            )
        return normalized  # type: ignore[return-value]


    def normalize_partition_frame(
        frame,
        date_partition: str,
        column_names: List[str],
        column_defs: List[dict],
        include_row_id: bool,
        row_id_start: int = 0,
    ):
        import pandas as pd

        frame.columns = [str(column) for column in frame.columns]
        if frame.columns.duplicated().any():
            frame = frame.loc[:, ~frame.columns.duplicated()]

        if "date" in frame.columns:
            date_series = frame["date"]
            if isinstance(date_series, pd.DataFrame):
                date_series = date_series.iloc[:, 0]
            parsed = pd.to_datetime(date_series, errors="coerce")
            fallback = date_series.map(lambda value: str(value) if pd.notna(value) else None)
            frame["date"] = parsed.dt.strftime("%Y.%m.%d").where(parsed.notna(), fallback)
        elif "date" in column_names:
            frame["date"] = date_partition

        for index in range(len(frame.columns)):
            series = frame.iloc[:, index]
            if isinstance(series, pd.DataFrame):
                series = series.iloc[:, 0]
            if not isinstance(series, pd.Series):
                series = pd.Series(series, index=frame.index)

            dtype_string = str(series.dtype)
            try:
                if series.dtype == object:
                    frame.iloc[:, index] = series.map(
                        lambda value: str(value) if pd.notna(value) else None
                    )
                elif "timedelta" in dtype_string:
                    frame.iloc[:, index] = (
                        series.dt.total_seconds() * 1e9
                    ).round().astype("Int64")
                elif "datetime64" in dtype_string:
                    frame.iloc[:, index] = pd.to_datetime(series, errors="coerce").dt.floor("us")
                else:
                    frame.iloc[:, index] = series
            except Exception:
                frame.iloc[:, index] = series.map(
                    lambda value: str(value) if pd.notna(value) else None
                )

        aligned = pd.DataFrame(index=frame.index)
        spark_types = {column["name"]: column.get("spark_type", "") for column in column_defs}
        for column_name in column_names:
            if column_name in frame.columns:
                selected = frame[column_name]
                if isinstance(selected, pd.DataFrame):
                    selected = selected.iloc[:, 0]
                aligned[column_name] = _coerce_to_expected_type(
                    selected, spark_types.get(column_name, "")
                )
            else:
                aligned[column_name] = None

        if include_row_id:
            aligned["__row_id"] = [
                f"{date_partition}:{row_id_start + row_index}"
                for row_index in range(len(aligned.index))
            ]

        return aligned


    def iter_records(frame, *, conversion_mode: ConversionMode) -> Iterator[Record]:
        if conversion_mode == "arrow_direct":
            yield from _iter_tuples(frame)
            return
        yield from _iter_dict_records(frame)


    def result_to_frame(result, *, conversion_mode: ConversionMode):
        import pandas as pd

        if conversion_mode == "arrow_pandas":
            frame, path = _result_to_pandas_via_arrow(result, allow_pd_fallback=False)
        else:
            frame, path = _result_to_pandas_via_arrow(result, allow_pd_fallback=True)
        record_conversion_path(path)
        if not isinstance(frame, pd.DataFrame):
            frame = pd.DataFrame(frame)
        return frame


    def result_len(result) -> int:
        if result is None:
            return 0
        try:
            return int(len(result))
        except Exception:
            return 0


    def _coerce_to_expected_type(series, spark_type: str):
        import pandas as pd

        normalized_type = str(spark_type or "").lower()
        if "string" in normalized_type:
            return series.map(lambda value: str(value) if pd.notna(value) else None)
        if "timestamp" in normalized_type:
            return pd.to_datetime(series, errors="coerce").dt.floor("us")
        if "boolean" in normalized_type:
            return series.map(
                lambda value: None
                if pd.isna(value)
                else str(value).strip().lower() in {"1", "true", "t", "yes", "y"}
            )
        if any(type_name in normalized_type for type_name in ("short", "integer", "long")):
            return pd.to_numeric(series, errors="coerce").astype("Int64")
        if any(type_name in normalized_type for type_name in ("float", "double")):
            return pd.to_numeric(series, errors="coerce").astype("float64")
        return series


    def _iter_dict_records(frame) -> Iterator[dict]:
        columns = list(frame.columns)
        for row in frame.itertuples(index=False, name=None):
            yield {columns[col_index]: _to_python(value) for col_index, value in enumerate(row)}


    def _iter_tuples(frame) -> Iterator[tuple]:
        for row in frame.itertuples(index=False, name=None):
            yield tuple(_to_python(value) for value in row)


    def _to_python(value):
        import pandas as pd

        if value is None:
            return None
        if value is pd.NaT:
            return None
        try:
            if pd.isna(value):
                return None
        except Exception:
            pass

        if hasattr(value, "to_pydatetime"):
            return value.to_pydatetime()
        if hasattr(value, "item"):
            try:
                return value.item()
            except Exception:
                pass
        return value


    def _result_to_pandas_via_arrow(result, *, allow_pd_fallback: bool):
        try:
            return result.pa(raw=True).to_pandas(timestamp_as_object=False), "pa_raw"
        except Exception:
            try:
                return result.pa().to_pandas(timestamp_as_object=False), "pa"
            except Exception:
                if not allow_pd_fallback:
                    raise
                return result.pd(), "pd_fallback"


    ########################################################
    # src/databricks/labs/community_connector/sources/kx_kdb/filesystem.py
    ########################################################

    DATE_PARTITION_RE = re.compile(r"^\d{4}\.\d{2}\.\d{2}$")


    def hdb_child_path(root_path: str, *parts: str) -> str:
        """Build a child path below a FUSE-mounted HDB root."""
        result = str(root_path or "").strip().rstrip("/")
        for part in parts:
            value = str(part or "").strip().strip("/")
            if value:
                result = f"{result}/{value}" if result else value
        return result


    def normalize_partition_date(raw_value: str | None) -> str | None:
        """Normalize supported date formats to KDB's YYYY.MM.DD partition format."""
        if raw_value is None:
            return None
        value = str(raw_value).strip()
        if not value:
            return None
        if DATE_PARTITION_RE.match(value):
            return value
        if re.match(r"^\d{4}-\d{2}-\d{2}$", value):
            return value.replace("-", ".")
        if re.match(r"^\d{4}/\d{2}/\d{2}$", value):
            return value.replace("/", ".")
        return value


    def _date_directories(root_path: str) -> list[Path]:
        if "://" in str(root_path):
            raise ValueError(
                f"HDB root path must be a FUSE/local directory, not a URI: {root_path}"
            )
        root = Path(root_path)
        if not root.exists():
            raise FileNotFoundError(f"HDB root path does not exist: {root_path}")
        if not root.is_dir():
            raise ValueError(f"HDB root path must be a directory: {root_path}")

        date_dirs = [
            child
            for child in root.iterdir()
            if child.is_dir() and DATE_PARTITION_RE.match(child.name)
        ]
        return sorted(date_dirs, key=lambda item: item.name)


    def list_date_partitions(root_path: str) -> list[str]:
        """List all date partitions found under an HDB root path."""
        return [path.name for path in _date_directories(root_path)]


    def discover_tables(root_path: str, sample_dates: int = 0) -> list[str]:
        """Discover logical table names by scanning date-partition directories."""
        date_dirs = _date_directories(root_path)
        if sample_dates and sample_dates > 0:
            date_dirs = date_dirs[:sample_dates]

        table_names: set[str] = set()
        for date_dir in date_dirs:
            for child in date_dir.iterdir():
                if child.is_dir():
                    table_names.add(child.name.lower())
        return sorted(table_names)


    def resolve_table_directory_name(
        root_path: str,
        table_name: str,
        sample_dates: int = 0,
    ) -> str:
        """Resolve a logical table name to the actual directory name on disk."""
        target = str(table_name).strip().lower()
        if not target:
            raise ValueError("table_name must be non-empty")

        date_dirs = _date_directories(root_path)
        if sample_dates and sample_dates > 0:
            date_dirs = date_dirs[:sample_dates]

        for date_dir in date_dirs:
            for child in date_dir.iterdir():
                if child.is_dir() and child.name.lower() == target:
                    return child.name

        raise ValueError(f"Table {table_name!r} was not found under {root_path}")


    def discover_table_partitions(
        root_path: str,
        table_name: str,
        start_date: str | None = None,
        end_date: str | None = None,
    ) -> list[str]:
        """Return all partitions that contain the requested table directory."""
        normalized_start = normalize_partition_date(start_date)
        normalized_end = normalize_partition_date(end_date)
        actual_table_name = resolve_table_directory_name(root_path, table_name)

        partitions = []
        for date_dir in _date_directories(root_path):
            partition_name = date_dir.name
            if normalized_start and partition_name < normalized_start:
                continue
            if normalized_end and partition_name > normalized_end:
                continue
            if (date_dir / actual_table_name).is_dir():
                partitions.append(partition_name)

        return partitions


    ########################################################
    # src/databricks/labs/community_connector/sources/kx_kdb/runtime.py
    ########################################################

    logger = logging.getLogger(__name__)

    DEFAULT_KDBX_INSTALLER_URL = (
        "https://portal.dl.kx.com/assets/raw/kdb-x/install_kdb/~latest~/install_kdb.sh"
    )
    PYKX_PIP_SPEC = "pykx==4.0.0b5"
    DEFAULT_OFFLINE_BUNDLE_NAME = "l64-bundle.zip"
    ARM_OFFLINE_BUNDLE_NAME = "l64arm-bundle.zip"

    KDBX_SECRET_SCOPE_OPTION = "kdbx_secret_scope"
    KDBX_INSTALL_BEARER_SECRET_KEY_OPTION = "kdbx_install_bearer_secret_key"
    KDBX_LICENSE_B64_SECRET_KEY_OPTION = "kdbx_license_b64_secret_key"
    KDBX_INSTALL_BEARER_TOKEN_OPTION = "kdbx_install_bearer_token"
    KDBX_LICENSE_B64_OPTION = "kdbx_license_b64"
    KDBX_LICENSE_FILE_PATH_OPTION = "kdbx_license_file_path"
    KDBX_OFFLINE_BUNDLE_PATH_OPTION = "kdbx_offline_bundle_path"
    KDBX_INSTALL_MODE_OPTION = "kdbx_install_mode"
    PYKX_INSTALL_SPEC_OPTION = "pykx_install_spec"

    _RUNTIME_LOCK = _PicklableLock()
    _PREPARED_RUNTIME_KEYS: set[tuple[str, int, int]] = set()
    _RUNTIME_HOME_CACHE: dict[str, Path] = {}
    _LOCAL_BUNDLE_DIR_CACHE: dict[str, Path] = {}
    _RUNTIME_HOME_OVERRIDE_ENV = "KDBX_RUNTIME_HOME"
    _LICENSE_FILE_NAMES = ("kc.lic", "k4.lic", "kx.lic")


    @dataclass(frozen=True)
    class PyKxRuntimeConfig:
        """Runtime configuration required to initialize PyKX safely."""

        license_directory: str
        installer_bearer_token: str | None = None
        license_b64: str | None = None
        installer_url: str = DEFAULT_KDBX_INSTALLER_URL
        offline_bundle_path: str | None = None
        pykx_install_spec: str | None = None

        @property
        def uses_installer(self) -> bool:
            if self.uses_offline_bundle:
                return True
            return bool(self.installer_bearer_token and self.license_b64)

        @property
        def uses_offline_bundle(self) -> bool:
            return bool(self.offline_bundle_path and self.license_b64)


    def normalize_license_directory(value: str) -> str:
        """Normalize a file-or-directory license path to the containing directory."""
        candidate = Path(str(value).strip())
        normalized = candidate if candidate.suffix == "" else candidate.parent
        return str(normalized)


    def build_runtime_config(
        options: dict[str, str],
        *,
        secret_resolver: Callable[[str, str], str] | None = None,
    ) -> PyKxRuntimeConfig:
        """Build the runtime config from connector options.

        Resolution order, highest priority first:
          1. Offline bundle install (no network) when ``kdbx_offline_bundle_path``
             is set or a bundle is found at a well-known location near the license
             directory, AND a license b64 can be resolved.
          2. Online installer bootstrap (curl + ``install_kdb.sh``) when both a
             bearer token and a license b64 are available.
          3. Legacy "license folder + preinstalled PyKX" mode otherwise.
        """
        license_directory = normalize_license_directory(str(options.get("license_volume_path", "")))
        explicit_bundle_path = str(options.get(KDBX_OFFLINE_BUNDLE_PATH_OPTION, "")).strip()
        pykx_install_spec = _option(options, PYKX_INSTALL_SPEC_OPTION)
        install_mode = _install_mode(options)

        direct_install_token = str(options.get(KDBX_INSTALL_BEARER_TOKEN_OPTION, "")).strip()
        direct_license_option = str(options.get(KDBX_LICENSE_B64_OPTION, "")).strip()
        license_file_b64 = ""
        if not direct_license_option:
            license_file_b64 = _read_license_file_b64(
                str(options.get(KDBX_LICENSE_FILE_PATH_OPTION, "")).strip()
            )
        direct_license_b64 = direct_license_option or license_file_b64

        if direct_license_b64 and explicit_bundle_path and install_mode != "online":
            return PyKxRuntimeConfig(
                license_directory=license_directory,
                installer_bearer_token=direct_install_token or None,
                license_b64=direct_license_b64,
                offline_bundle_path=explicit_bundle_path,
                pykx_install_spec=pykx_install_spec,
            )

        direct_supplied = [bool(direct_install_token), bool(direct_license_option)]
        if any(direct_supplied) and not all(direct_supplied):
            raise ValueError(
                "KDB-X bootstrap requires both "
                f"{KDBX_INSTALL_BEARER_TOKEN_OPTION!r} and {KDBX_LICENSE_B64_OPTION!r} "
                "when using direct connection options."
            )
        if all(direct_supplied):
            config = PyKxRuntimeConfig(
                license_directory=license_directory,
                installer_bearer_token=direct_install_token,
                license_b64=direct_license_b64,
                pykx_install_spec=pykx_install_spec,
            )
            return config if install_mode == "online" else _maybe_offline(config, explicit_bundle_path)

        if license_file_b64:
            if install_mode == "online":
                raise ValueError(
                    f"{KDBX_INSTALL_MODE_OPTION}='online' requires an installer bearer token "
                    "and license b64, not only a license file."
                )
            return _maybe_offline(
                PyKxRuntimeConfig(
                    license_directory=license_directory,
                    license_b64=license_file_b64,
                    pykx_install_spec=pykx_install_spec,
                ),
                explicit_bundle_path,
            )

        secret_scope = str(options.get(KDBX_SECRET_SCOPE_OPTION, "")).strip()
        install_token_key = str(options.get(KDBX_INSTALL_BEARER_SECRET_KEY_OPTION, "")).strip()
        license_b64_key = str(options.get(KDBX_LICENSE_B64_SECRET_KEY_OPTION, "")).strip()

        supplied = [bool(secret_scope), bool(install_token_key), bool(license_b64_key)]
        if any(supplied) and not all(supplied):
            raise ValueError(
                "KDB-X bootstrap requires all of "
                f"{KDBX_SECRET_SCOPE_OPTION!r}, "
                f"{KDBX_INSTALL_BEARER_SECRET_KEY_OPTION!r}, and "
                f"{KDBX_LICENSE_B64_SECRET_KEY_OPTION!r} together."
            )

        if not all(supplied):
            return PyKxRuntimeConfig(
                license_directory=license_directory,
                pykx_install_spec=pykx_install_spec,
            )

        resolver = secret_resolver or _resolve_databricks_secret
        installer_bearer_token = resolver(secret_scope, install_token_key).strip()
        license_b64 = resolver(secret_scope, license_b64_key).strip()
        if not installer_bearer_token or not license_b64:
            raise ValueError(
                "Resolved empty KDB-X bootstrap secret value. Check the configured "
                "secret scope and secret keys."
            )

        config = PyKxRuntimeConfig(
            license_directory=license_directory,
            installer_bearer_token=installer_bearer_token,
            license_b64=license_b64,
            pykx_install_spec=pykx_install_spec,
        )
        return config if install_mode == "online" else _maybe_offline(config, explicit_bundle_path)


    def _option(options: dict[str, str], key: str) -> str | None:
        value = str(options.get(key, "")).strip()
        return value or None


    def _install_mode(options: dict[str, str]) -> str:
        value = str(options.get(KDBX_INSTALL_MODE_OPTION, "auto")).strip().lower()
        mode = value or "auto"
        if mode not in {"auto", "online", "offline"}:
            raise ValueError(
                f"Unsupported {KDBX_INSTALL_MODE_OPTION} {mode!r}. "
                "Expected 'auto', 'online', or 'offline'."
            )
        return mode


    def _read_license_file_b64(path: str) -> str:
        if not path:
            return ""
        candidate = Path(path)
        if candidate.is_dir():
            for file_name in _LICENSE_FILE_NAMES:
                license_file = candidate / file_name
                if license_file.is_file():
                    return base64.b64encode(license_file.read_bytes()).decode("ascii")
            return ""
        if candidate.is_file():
            return base64.b64encode(candidate.read_bytes()).decode("ascii")
        return ""


    def _maybe_offline(config: PyKxRuntimeConfig, explicit_bundle_path: str) -> PyKxRuntimeConfig:
        """Promote a config to offline-install mode when a bundle is available.

        The offline path requires only the license b64, but the bearer token is
        preserved when available so worker-side installs can fall back to the
        online installer if a UC volume bundle cannot be localized.
        """
        if not config.license_b64:
            return config
        bundle_path = (
            explicit_bundle_path
            or _probe_offline_bundle(config.license_directory)
            or ""
        )
        if not bundle_path:
            return config
        return PyKxRuntimeConfig(
            license_directory=config.license_directory,
            installer_bearer_token=config.installer_bearer_token,
            license_b64=config.license_b64,
            offline_bundle_path=bundle_path,
            pykx_install_spec=config.pykx_install_spec,
        )


    def _probe_offline_bundle(license_directory: str) -> str | None:
        """Look for a pre-staged KDB-X install bundle near the license directory.

        Probed in order:
          - ``<license_directory>/l64-bundle.zip``
          - ``<license_directory>/../kdbx/l64-bundle.zip``
        Returns the first existing file path or ``None``.
        """
        if not license_directory:
            return None
        base = Path(license_directory)
        for candidate in _offline_bundle_candidates(base):
            try:
                if candidate.is_file():
                    return str(candidate)
            except OSError:
                continue
        return None


    def _offline_bundle_candidates(base: Path) -> tuple[Path, ...]:
        return tuple(
            candidate
            for bundle_name in _offline_bundle_names_for_platform()
            for candidate in (
                base / bundle_name,
                base.parent / "kdbx" / bundle_name,
            )
        )


    def _bundle_path_status(paths: tuple[Path, ...]) -> str:
        statuses = []
        for path in paths:
            try:
                statuses.append(
                    f"{path}: exists={path.exists()} is_file={path.is_file()}"
                )
            except OSError as exc:
                statuses.append(f"{path}: error={type(exc).__name__}: {exc}")
        return "; ".join(statuses)


    def _offline_bundle_names_for_platform() -> tuple[str, ...]:
        machine = platform.machine().lower()
        if machine in {"aarch64", "arm64"}:
            return (ARM_OFFLINE_BUNDLE_NAME, DEFAULT_OFFLINE_BUNDLE_NAME)
        return (DEFAULT_OFFLINE_BUNDLE_NAME,)


    def prepare_pykx(config: PyKxRuntimeConfig):
        """Install/configure KDB-X and import PyKX after license setup."""
        runtime_key = (
            config.license_directory,
            len(config.installer_bearer_token or ""),
            len(config.license_b64 or ""),
        )

        with _RUNTIME_LOCK:
            if config.uses_installer and runtime_key not in _PREPARED_RUNTIME_KEYS:
                logger.info("Bootstrapping KDB-X and PyKX for serverless execution.")
                _install_kdbx(config)
                _PREPARED_RUNTIME_KEYS.add(runtime_key)

            _apply_pykx_environment(config)
            importlib.invalidate_caches()

            if "pykx" in sys.modules:
                return sys.modules["pykx"]
            try:
                return importlib.import_module("pykx")
            except ModuleNotFoundError as exc:
                if exc.name != "pykx" or not config.uses_installer:
                    raise

            _ensure_pykx_package(config)
            importlib.invalidate_caches()
            return importlib.import_module("pykx")


    def _resolve_databricks_secret(scope: str, key: str) -> str:
        try:
            from databricks.sdk.runtime import (  # pylint: disable=import-error,no-name-in-module
                dbutils as runtime_dbutils,
            )

            return runtime_dbutils.secrets.get(scope, key)
        except Exception:
            pass

        try:
            from pyspark.dbutils import DBUtils  # pylint: disable=import-error,no-name-in-module
            from pyspark.sql import SparkSession
        except Exception as exc:
            raise RuntimeError(
                "Unable to import Databricks secret helpers. Resolve KDB-X secrets on "
                "the driver before using the connector."
            ) from exc

        spark = SparkSession.getActiveSession()
        if spark is None:
            get_default_session = getattr(SparkSession, "getDefaultSession", None)
            if callable(get_default_session):
                spark = get_default_session()  # pylint: disable=not-callable
        if spark is None:
            spark = getattr(SparkSession, "_instantiatedSession", None)
        if spark is None:
            try:
                spark = SparkSession.builder.getOrCreate()  # pylint: disable=no-member
            except Exception as exc:
                raise RuntimeError(
                    "A SparkSession is required to resolve KDB-X secrets for the connector."
                ) from exc
        if spark is None:
            raise RuntimeError("A SparkSession is required to resolve KDB-X secrets for the connector.")

        return DBUtils(spark).secrets.get(scope, key)


    def _install_kdbx(config: PyKxRuntimeConfig) -> None:
        if not config.uses_installer:
            return
        if config.uses_offline_bundle:
            _install_kdbx_offline(config)
        else:
            _install_kdbx_online(config)


    def _install_kdbx_online(config: PyKxRuntimeConfig) -> None:
        runtime_home = _runtime_home_directory()
        runtime_home.mkdir(parents=True, exist_ok=True)
        # The KDB-X installer auto-selects "$HOME/.kx" as the install location and
        # aborts in non-interactive mode if it cannot create that directory. On
        # serverless executors with read-only or restricted /tmp, pre-creating it
        # here avoids the "Cannot create directory" failure surfaced from
        # install_kdb.sh.
        (runtime_home / ".kx").mkdir(parents=True, exist_ok=True)

        with tempfile.TemporaryDirectory() as tmpdir:
            installer_path = Path(tmpdir) / "install_kdb.sh"
            download = subprocess.run(
                [
                    "curl",
                    "-sSLO",
                    "--fail-with-body",
                    "--oauth2-bearer",
                    config.installer_bearer_token or "",
                    config.installer_url,
                ],
                cwd=tmpdir,
                capture_output=True,
                text=True,
                timeout=180,
            )
            if download.returncode != 0:
                raise RuntimeError(
                    "KDB-X installer download failed with rc="
                    f"{download.returncode}: {_command_tail(download.stderr)}"
                )

            install_env = {
                **os.environ,
                "HOME": str(runtime_home),
                # Override any inherited TERM (e.g. "unknown" on serverless DLT
                # analyzers) so the installer's tput calls don't blow up.
                "TERM": "dumb",
            }
            install = subprocess.run(
                [
                    "bash",
                    str(installer_path),
                    "-y",
                    "--b64lic",
                    config.license_b64 or "",
                ],
                cwd=tmpdir,
                env=install_env,
                capture_output=True,
                text=True,
                timeout=1200,
            )
            if install.returncode != 0:
                raise RuntimeError(
                    "install_kdb.sh failed with rc="
                    f"{install.returncode}. stdout tail: {_command_tail(install.stdout)}. "
                    f"stderr tail: {_command_tail(install.stderr)}"
                )


    def _install_kdbx_offline(config: PyKxRuntimeConfig) -> None:
        """Install KDB-X from a pre-staged offline bundle (no network access)."""
        runtime_home = _runtime_home_directory()
        runtime_home.mkdir(parents=True, exist_ok=True)
        (runtime_home / ".kx").mkdir(parents=True, exist_ok=True)

        bundle_path = _localize_offline_bundle(config.offline_bundle_path or "")

        with tempfile.TemporaryDirectory() as tmpdir:
            try:
                with zipfile.ZipFile(bundle_path) as zf:
                    zf.extractall(tmpdir)
            except zipfile.BadZipFile as exc:
                raise RuntimeError(
                    f"Offline KDB-X bundle at {str(bundle_path)!r} is not a valid zip."
                ) from exc

            installer_path = Path(tmpdir) / "install_kdb.sh"
            if not installer_path.is_file():
                raise RuntimeError(
                    f"Offline KDB-X bundle at {str(bundle_path)!r} does not contain "
                    "install_kdb.sh."
                )
            installer_path.chmod(0o755)

            install_env = {
                **os.environ,
                "HOME": str(runtime_home),
                "TERM": "dumb",
            }
            install = subprocess.run(
                [
                    "bash",
                    str(installer_path),
                    "--offline",
                    # Without `-y` the script falls into interactive mode and hangs
                    # on its first prompt, eventually triggering ``TimeoutExpired``.
                    "-y",
                    "--b64lic",
                    config.license_b64 or "",
                ],
                cwd=tmpdir,
                env=install_env,
                capture_output=True,
                text=True,
                timeout=1200,
            )
            if install.returncode != 0:
                raise RuntimeError(
                    "install_kdb.sh --offline failed with rc="
                    f"{install.returncode}. stdout tail: {_command_tail(install.stdout)}. "
                    f"stderr tail: {_command_tail(install.stderr)}"
                )


    def _ensure_pykx_package(config: PyKxRuntimeConfig) -> None:
        spec = config.pykx_install_spec or PYKX_PIP_SPEC
        target = str(_runtime_home_directory() / "pykx_pkgs")
        command = [
            sys.executable,
            "-I",
            "-m",
            "pip",
            "install",
            "--quiet",
            "--ignore-installed",
            "--target",
            target,
        ]
        if not _is_wheel_or_path(spec):
            command.append("--pre")
        command.append(spec)
        pip_env = dict(os.environ)
        # Spark workers inherit a PYTHONPATH containing JAR paths. Pip scans every
        # entry as a possible distribution and can fail with PermissionError on
        # protected Databricks JARs. The isolated interpreter and clean path keep
        # the fallback install confined to ``target``.
        pip_env.pop("PYTHONPATH", None)
        pip_env.pop("PYTHONHOME", None)
        pip_install = subprocess.run(
            command,
            capture_output=True,
            text=True,
            timeout=1200,
            env=pip_env,
        )
        if pip_install.returncode != 0:
            raise RuntimeError(
                f"Failed to install PyKX package {spec!r}. stdout tail: "
                f"{_command_tail(pip_install.stdout)}. stderr tail: "
                f"{_command_tail(pip_install.stderr)}"
            )
        if target not in sys.path:
            sys.path.insert(0, target)
        existing_pythonpath = os.environ.get("PYTHONPATH", "")
        if target not in existing_pythonpath.split(os.pathsep):
            os.environ["PYTHONPATH"] = (
                f"{target}{os.pathsep}{existing_pythonpath}" if existing_pythonpath else target
            )


    def _is_wheel_or_path(spec: str) -> bool:
        normalized = str(spec or "").strip()
        return normalized.endswith(".whl") or "/" in normalized or normalized.startswith("dbfs:")


    def _localize_offline_bundle(bundle_path: str) -> Path:
        """Copy an offline bundle to local temp storage before opening it as a zip."""
        source = str(bundle_path or "").strip()
        if not source:
            raise RuntimeError("Offline KDB-X install bundle path is empty.")

        local_dir = _local_bundle_directory()
        local_path = local_dir / Path(source).name
        if _path_is_file(local_path):
            return local_path

        try:
            source_path = Path(source)
            if _path_is_file(source_path):
                shutil.copyfile(source_path, local_path)
                return local_path
        except Exception as exc:
            logger.debug("Direct copy of KDB-X bundle failed: %s", exc)

        errors = []
        for src_uri in _dbutils_source_uris(source):
            try:
                _copy_with_dbutils(src_uri, f"file:{local_path}")
                if _path_is_file(local_path):
                    return local_path
            except Exception as exc:
                errors.append(f"{src_uri}: {exc}")

        raise RuntimeError(
            f"Offline KDB-X install bundle could not be localized from {source!r}. "
            f"source status: {_bundle_path_status((Path(source),))}. "
            f"dbutils attempts: {'; '.join(errors) if errors else 'none'}"
        )


    def _local_bundle_directory() -> Path:
        """Return a process-owned local bundle cache directory."""
        cached = _LOCAL_BUNDLE_DIR_CACHE.get("path")
        if cached is None:
            cached = Path(tempfile.mkdtemp(prefix=f"kdbx-bundles-{os.getpid()}-"))
            cached.mkdir(parents=True, exist_ok=True)
            _LOCAL_BUNDLE_DIR_CACHE["path"] = cached
        return cached


    def _path_is_file(path: Path) -> bool:
        try:
            return path.is_file()
        except OSError:
            return False


    def _dbutils_source_uris(source: str) -> tuple[str, ...]:
        if source.startswith("dbfs:") or source.startswith("file:"):
            return (source,)
        if source.startswith("/"):
            return (f"file:{source}", source)
        return (source,)


    def _copy_with_dbutils(src: str, dst: str) -> None:
        try:
            from databricks.sdk.runtime import (  # pylint: disable=import-error,no-name-in-module
                dbutils as runtime_dbutils,
            )

            runtime_dbutils.fs.cp(src, dst, True)
            return
        except Exception:
            pass

        try:
            from pyspark.dbutils import DBUtils  # pylint: disable=import-error,no-name-in-module
            from pyspark.sql import SparkSession
        except Exception as exc:
            raise RuntimeError("dbutils is not available for bundle localization") from exc

        spark = SparkSession.getActiveSession() or getattr(SparkSession, "_instantiatedSession", None)
        if spark is None:
            spark = SparkSession.builder.getOrCreate()  # pylint: disable=no-member
        DBUtils(spark).fs.cp(src, dst, True)


    def _resolve_qlic_dir(config: PyKxRuntimeConfig) -> str:
        license_dir = Path(config.license_directory) if config.license_directory else None
        if license_dir and license_dir.is_dir():
            for file_name in _LICENSE_FILE_NAMES:
                if (license_dir / file_name).exists():
                    return str(license_dir)

        if config.license_b64:
            target = _runtime_home_directory() / "qlic"
            target.mkdir(parents=True, exist_ok=True)
            (target / "kc.lic").write_bytes(base64.b64decode(config.license_b64))
            return str(target)

        if license_dir:
            return str(license_dir)
        target = _runtime_home_directory() / "qlic"
        target.mkdir(parents=True, exist_ok=True)
        return str(target)


    def _apply_pykx_environment(config: PyKxRuntimeConfig) -> None:
        runtime_home = _runtime_home_directory()
        runtime_home.mkdir(parents=True, exist_ok=True)
        target = Path(_resolve_qlic_dir(config))
        os.environ["HOME"] = str(runtime_home)
        os.environ["QLIC"] = str(target)
        os.environ["PYKX_LICENSED"] = "true"
        if config.license_b64:
            os.environ["KDB_LICENSE_B64"] = config.license_b64
        kx_bin = runtime_home / ".kx" / "bin"
        existing_path = os.environ.get("PATH", "")
        if kx_bin.exists():
            os.environ["PATH"] = f"{kx_bin}:{existing_path}" if existing_path else str(kx_bin)
        if not config.license_b64 and _path_exists(target):
            os.chdir(str(target))


    def _path_exists(path: Path) -> bool:
        try:
            return path.exists()
        except OSError:
            return False


    def _command_tail(value: str, limit: int = 1200) -> str:
        text = str(value or "").strip()
        if len(text) <= limit:
            return text
        return text[-limit:]


    def _runtime_home_directory() -> Path:
        """Return a writable scratch directory used as ``HOME`` during install.

        Honors ``KDBX_RUNTIME_HOME`` when set (useful for tests and pipelines that
        want a stable, well-known path). Otherwise creates a unique directory via
        ``tempfile.mkdtemp`` to guarantee writability on locked-down serverless
        runtimes where a static ``/tmp/kdbx-home`` may not be creatable. The
        chosen path is cached for the lifetime of the process.
        """
        cached = _RUNTIME_HOME_CACHE.get("path")
        if cached is not None:
            return cached

        override = os.environ.get(_RUNTIME_HOME_OVERRIDE_ENV, "").strip()
        if override:
            path = Path(override)
            path.mkdir(parents=True, exist_ok=True)
        else:
            path = Path(tempfile.mkdtemp(prefix="kdbx-home-"))

        _RUNTIME_HOME_CACHE["path"] = path
        return path


    ########################################################
    # src/databricks/labs/community_connector/sources/kx_kdb/schema.py
    ########################################################

    logger = logging.getLogger(__name__)

    Q_META_TYPE_TO_SPARK = {
        "b": "BooleanType",
        "x": "ShortType",
        "h": "ShortType",
        "i": "IntegerType",
        "j": "LongType",
        "e": "FloatType",
        "f": "DoubleType",
        "c": "StringType",
        "s": "StringType",
        "p": "TimestampType",
        "d": "StringType",
        "z": "TimestampType",
        "n": "LongType",
        "u": "StringType",
        "v": "StringType",
        "t": "StringType",
        "g": "StringType",
        " ": "StringType",
        "C": "StringType",
    }


    def _dedupe_column_defs(columns: List[dict]) -> List[dict]:
        """Return column definitions with unique case-insensitive names."""
        deduped: List[dict] = []
        seen = set()
        for column in columns:
            name = str(column.get("name", "")).strip()
            if not name:
                continue
            lowered = name.lower()
            if lowered in seen:
                logger.warning("Dropping duplicate inferred column: %s", name)
                continue
            seen.add(lowered)
            deduped.append(
                {"name": name, "spark_type": str(column.get("spark_type", "StringType"))}
            )
        return deduped


    def _clean_type_char(type_char) -> str:
        value = type_char
        if isinstance(value, (bytes, bytearray)):
            value = value.decode("latin1", "ignore")
        text = str(value or "").strip().strip("`").strip()
        if (
            len(text) >= 3
            and text[0] in {"b", "B"}
            and text[1] in {"'", '"'}
            and text[-1] in {"'", '"'}
        ):
            text = text[2:-1]
        text = text.strip().strip("'").strip('"').strip()
        return text[-1] if text else ""


    def _map_meta_type_char(type_char) -> str:
        return Q_META_TYPE_TO_SPARK.get(_clean_type_char(type_char), "StringType")


    def infer_schema_from_partition(
        hdb_root_path: str,
        kdb_table_name: str,
        date_partition: str,
        runtime_config: PyKxRuntimeConfig,
    ) -> List[dict]:
        """Infer column definitions from a single KDB partition."""
        kx = prepare_pykx(runtime_config)
        columns = _try_infer_via_db_query(kx, hdb_root_path, kdb_table_name)
        if columns is None:
            columns = _try_infer_via_get_partition(
                kx, hdb_root_path, kdb_table_name, date_partition
            )
        if columns is None:
            columns = _try_infer_via_splayed_column_files(
                kx, hdb_root_path, kdb_table_name, date_partition
            )

        if columns is None:
            raise RuntimeError(
                f"Could not infer schema for {kdb_table_name} from "
                f"{_partition_table_path(hdb_root_path, kdb_table_name, date_partition)}"
            )

        return _with_date_column(columns)


    def _with_date_column(columns: List[dict]) -> List[dict]:
        has_date = any(str(column.get("name", "")).strip().lower() == "date" for column in columns)
        result = []
        if not has_date:
            result.append({"name": "date", "spark_type": "StringType"})
        result.extend(columns)
        return _dedupe_column_defs(result)


    def _try_infer_via_splayed_column_files(
        kx,
        hdb_root_path: str,
        table_name: str,
        date_partition: str,
    ) -> Optional[List[dict]]:
        """Infer schema from a splayed table directory without opening the full HDB."""
        try:
            table_path = _partition_table_path(hdb_root_path, table_name, date_partition)
            columns = []
            for column_name in _column_names_from_splayed_d(kx, table_path):
                columns.append(
                    {
                        "name": column_name,
                        "spark_type": _infer_column_file_type(
                            kx, hdb_child_path(table_path, column_name)
                        ),
                    }
                )
            return columns if columns else None
        except Exception as exc:
            logger.debug("Splayed file schema inference failed for %s: %s", table_name, exc)
            return None


    def _column_names_from_splayed_d(kx, table_path: str) -> list[str]:
        result = kx.q("{[p] get hsym p}", hdb_child_path(table_path, ".d"))
        return _q_list_to_strings(result)


    def _infer_column_file_type(kx, column_path: str) -> str:
        type_chars = _q_list_to_strings(kx.q("{[p] string .Q.ty type get hsym p}", column_path))
        return _map_meta_type_char(type_chars[0] if type_chars else "")


    def _q_list_to_strings(value) -> list[str]:
        if hasattr(value, "py"):
            try:
                value = value.py()
            except Exception:
                pass
        if hasattr(value, "tolist"):
            try:
                value = value.tolist()
            except Exception:
                pass
        if isinstance(value, (str, bytes)):
            values = [value]
        else:
            values = list(value)
        result = []
        for item in values:
            text = item.decode("utf-8") if isinstance(item, bytes) else str(item)
            text = text.strip().strip("`")
            if text:
                result.append(text)
        return result


    def _columns_from_meta(kx, table_expr: str) -> Optional[List[dict]]:
        names = _q_list_to_strings(kx.q(f"string (0!meta {table_expr})`c"))
        type_chars = _q_list_to_strings(kx.q(f"string (0!meta {table_expr})`t"))
        if not names:
            return None
        return [
            {
                "name": names[index],
                "spark_type": _map_meta_type_char(type_chars[index] if index < len(type_chars) else ""),
            }
            for index in range(len(names))
        ]


    def _try_infer_via_db_query(kx, hdb_root_path: str, table_name: str) -> Optional[List[dict]]:
        try:
            kx.DB(path=hdb_root_path)
            return _columns_from_meta(kx, table_name)
        except Exception as exc:
            logger.debug("DB schema inference failed for %s: %s", table_name, exc)
            return None


    def _try_infer_via_get_partition(
        kx,
        hdb_root_path: str,
        table_name: str,
        date_partition: str,
    ) -> Optional[List[dict]]:
        try:
            partition_path = _partition_table_path(hdb_root_path, table_name, date_partition)
            kx.q("{[p] __lakeflow_schema_tmp: get hsym p}", partition_path)
            columns = _columns_from_meta(kx, "__lakeflow_schema_tmp")

            try:
                kx.q("delete __lakeflow_schema_tmp from `.")
            except Exception:
                pass
            return columns if columns else None
        except Exception as exc:
            logger.debug("Partition schema inference failed for %s: %s", table_name, exc)
            return None


    def _partition_table_path(
        hdb_root_path: str,
        table_name: str,
        date_partition: str,
    ) -> str:
        return hdb_child_path(hdb_root_path, date_partition, table_name)


    def columns_to_spark_schema(columns: List[dict]):
        """Convert a list of column definitions to a StructType."""
        from pyspark.sql.types import (
            BooleanType,
            DoubleType,
            FloatType,
            IntegerType,
            LongType,
            ShortType,
            StringType,
            StructField,
            StructType,
            TimestampType,
        )

        type_map = {
            "BooleanType": BooleanType(),
            "ShortType": ShortType(),
            "IntegerType": IntegerType(),
            "LongType": LongType(),
            "FloatType": FloatType(),
            "DoubleType": DoubleType(),
            "StringType": StringType(),
            "TimestampType": TimestampType(),
        }

        fields = []
        for column in _dedupe_column_defs(columns):
            fields.append(
                StructField(
                    column["name"],
                    type_map.get(column["spark_type"], StringType()),
                    nullable=True,
                )
            )
        return StructType(fields)


    def serialize_columns(columns: List[dict]) -> str:
        return json.dumps(columns)


    def deserialize_columns(columns_json: str) -> List[dict]:
        return json.loads(columns_json)


    ########################################################
    # src/databricks/labs/community_connector/sources/kx_kdb/sym_reader.py
    ########################################################

    logger = logging.getLogger(__name__)

    # Keep each date×sym slice chunk small enough for serverless Python memory limits.
    _ROW_CHUNK_SIZE = 10_000


    def _partition_path(hdb_root_path: str, date_partition: str, kdb_table_name: str) -> str:
        return hdb_child_path(hdb_root_path, date_partition, kdb_table_name)


    def _sym_file_path(hdb_root_path: str) -> str:
        return hdb_child_path(hdb_root_path, "sym")


    def _load_sym_into_q(kx, sym_file: str) -> None:
        """Load the root sym enumeration into the q session."""
        try:
            kx.q("{[p] `sym set get hsym p}", sym_file)
        except Exception:
            kx.q("sym: get `:", sym_file)


    def _ensure_sym_loaded(kx, hdb_root_path: str) -> str:
        sym_file = _sym_file_path(hdb_root_path)
        _load_sym_into_q(kx, sym_file)
        return sym_file


    def load_sym_enumeration(hdb_root_path: str, runtime_config: PyKxRuntimeConfig) -> list[str]:
        """Load the HDB sym enumeration once on the driver."""
        symbols, _ = load_sym_enumeration_with_indices(hdb_root_path, runtime_config)
        return symbols


    def load_sym_enumeration_with_indices(
        hdb_root_path: str, runtime_config: PyKxRuntimeConfig
    ) -> tuple[list[str], dict[str, int]]:
        """Return sym strings and their KDB enumeration indices."""
        kx = prepare_pykx(runtime_config)
        sym_file = _ensure_sym_loaded(kx, hdb_root_path)
        try:
            sym_values = kx.q("{[p] get hsym p}", sym_file)
        except Exception:
            sym_values = kx.q("get `:", sym_file)
        symbols = _symbols_to_strings(sym_values)
        indices = {symbol: index for index, symbol in enumerate(symbols)}
        return symbols, indices


    def _symbols_to_strings(value) -> list[str]:
        if hasattr(value, "py"):
            try:
                value = value.py()
            except Exception:
                pass
        if hasattr(value, "tolist"):
            try:
                value = value.tolist()
            except Exception:
                pass
        if isinstance(value, (str, bytes)):
            values: Iterable = [value]
        else:
            try:
                values = list(value)
            except TypeError:
                values = [value]

        symbols = []
        for item in values:
            text = _symbol_text(item)
            if text:
                symbols.append(text)
        return symbols


    def _symbol_text(value) -> str:
        text = value.decode("utf-8") if isinstance(value, bytes) else str(value)
        text = text.strip().strip("`")
        while text.endswith("/"):
            text = text[:-1]
        if "/" in text:
            text = text.rsplit("/", 1)[-1]
        return text


    def read_kdb_date_sym_records(
        *,
        hdb_root_path: str,
        kdb_table_name: str,
        date_partition: str,
        symbol: str,
        sym_index: int,
        runtime_config: PyKxRuntimeConfig,
        column_defs: List[dict],
        sym_column: str = "sym",
        conversion_mode: str = DEFAULT_PARTITION_CONVERSION_MODE,
    ) -> Iterator[Record]:
        """Read one HDB date partition filtered to a single symbol."""
        import gc

        mode = normalize_conversion_mode(conversion_mode)
        kx = prepare_pykx(runtime_config)

        column_names = [column["name"] for column in column_defs]
        sym_column = sym_column.strip()
        if not sym_column:
            raise ValueError("sym_column must be a non-empty KDB partition column name")

        try:
            if sym_index < 0:
                return

            partition_path = _partition_path(hdb_root_path, date_partition, kdb_table_name)
            existing_columns = _existing_partition_columns(partition_path, column_names)
            if sym_column.lower() not in {column.lower() for column in existing_columns}:
                logger.warning(
                    "Skipping %s because required sym column %r is missing.",
                    partition_path,
                    sym_column,
                )
                return

            column_paths = [f"{partition_path}/{column_name}" for column_name in existing_columns]
            sym_path = f"{partition_path}/{sym_column}"
            _prepare_symbol_row_indices(kx, sym_path, sym_index)
            row_count = _symbol_row_count(kx)
            if row_count <= 0:
                return

            for offset in range(0, row_count, _ROW_CHUNK_SIZE):
                frame = _read_symbol_chunk(
                    kx,
                    column_paths,
                    existing_columns,
                    offset,
                    _ROW_CHUNK_SIZE,
                )
                if frame is None or len(frame.index) == 0:
                    continue

                import pandas as pd

                if sym_column in frame.columns:
                    key_series = frame[sym_column]
                    if isinstance(key_series, pd.DataFrame):
                        key_series = key_series.iloc[:, 0]
                    frame[sym_column] = key_series.astype(str)
                elif sym_column in column_names:
                    frame[sym_column] = symbol

                normalized = normalize_partition_frame(
                    frame=frame,
                    date_partition=date_partition,
                    column_names=column_names,
                    column_defs=column_defs,
                    include_row_id=False,
                    row_id_start=offset,
                )
                yield from iter_records(normalized, conversion_mode=mode)

                del frame, normalized
                gc.collect()
        finally:
            gc.collect()


    def _existing_partition_columns(partition_path: str, column_names: list[str]) -> list[str]:
        """Return requested physical column files that exist in a splayed partition."""
        base = Path(partition_path)
        existing = []
        for column_name in column_names:
            if column_name == "date":
                continue
            if (base / column_name).is_file():
                existing.append(column_name)
            else:
                logger.debug("Missing KDB column file: %s", base / column_name)
        return existing


    def _prepare_symbol_row_indices(kx, sym_path: str, sym_index: int) -> None:
        """Materialize row indices for one sym value in the q session."""
        kx.q(
            "{[sympath; symi] `chunk_idx set where (get hsym sympath)=symi}",
            sym_path,
            int(sym_index),
        )


    def _symbol_row_count(kx) -> int:
        return _scalar_int(kx.q("count chunk_idx"))


    def _scalar_int(value) -> int:
        if hasattr(value, "py"):
            try:
                value = value.py()
            except Exception:
                pass
        if hasattr(value, "item"):
            try:
                value = value.item()
            except Exception:
                pass
        return int(value)


    def _read_symbol_chunk(
        kx,
        column_paths: list[str],
        columns: list[str],
        row_off: int,
        nrows: int,
    ):
        """Read one row slice for a symbol without materializing all indices in Python."""
        row_indices = kx.q(
            "{[row_off; nrows] "
            "m: nrows & (count chunk_idx - row_off); "
            "$[m<=0; `long$(); chunk_idx[row_off+til m]]}",
            int(row_off),
            int(nrows),
        )
        if _is_empty_collection(row_indices):
            return None
        return _read_columns_for_indices(kx, column_paths, columns, row_indices)


    def _symbol_row_indices(kx, sym_path: str, sym_index: int):
        """Return row indices for one sym enumeration value within a partition sym column."""
        return kx.q(
            "{[sympath; symi] where (get hsym sympath)=symi}",
            sym_path,
            int(sym_index),
        )


    def _index_values(indices) -> list[int]:
        if indices is None:
            return []

        raw = indices
        if hasattr(raw, "py"):
            try:
                raw = raw.py()
            except Exception:
                pass
        if hasattr(raw, "tolist"):
            try:
                raw = raw.tolist()
            except Exception:
                pass

        if isinstance(raw, (str, bytes)):
            return [int(raw)]

        try:
            values = list(raw)
        except TypeError:
            return [_scalar_int(raw)]

        flattened: list[int] = []
        for value in values:
            if isinstance(value, (list, tuple)):
                flattened.extend(_index_values(value))
            else:
                flattened.append(_scalar_int(value))
        return flattened


    def _is_empty_collection(value) -> bool:
        if value is None:
            return True
        try:
            return len(value) == 0
        except TypeError:
            return False


    def _read_columns_for_indices(kx, column_paths: list[str], columns: list[str], indices):
        """Read selected rows from existing splayed column files."""
        if _is_empty_collection(indices):
            return None
        vectors = kx.q(
            "{[column_paths; idx] {[p; idx] (get hsym p) idx} each column_paths}",
            column_paths,
            indices,
        )
        return _column_vectors_to_frame(columns, vectors)


    def _read_existing_columns_for_symbol(
        kx,
        partition_path: str,
        columns: list[str],
        sym_index: int,
    ):
        """Read all rows for one sym index from existing splayed column files."""
        column_paths = [f"{partition_path}/{column_name}" for column_name in columns]
        sym_path = f"{partition_path}/sym"
        _prepare_symbol_row_indices(kx, sym_path, sym_index)
        return _read_symbol_chunk(kx, column_paths, columns, 0, _symbol_row_count(kx))


    def _column_vectors_to_frame(columns: list[str], vectors):
        import pandas as pd

        if vectors is None:
            return pd.DataFrame()

        raw_vectors = vectors
        if hasattr(raw_vectors, "py"):
            try:
                raw_vectors = raw_vectors.py()
            except Exception:
                pass

        try:
            items = list(raw_vectors)
        except TypeError:
            items = [raw_vectors]

        if not items:
            return pd.DataFrame()

        series_by_name = {}
        for column_name, vector in zip(columns, items):
            series_by_name[column_name] = _vector_to_values(vector)

        return pd.DataFrame(series_by_name)


    def _vector_to_values(vector):
        import pandas as pd

        if hasattr(vector, "py"):
            try:
                vector = vector.py()
            except Exception:
                pass
        if hasattr(vector, "pd"):
            try:
                vector = vector.pd()
            except Exception:
                pass
        if hasattr(vector, "tolist"):
            try:
                vector = vector.tolist()
            except Exception:
                pass

        if isinstance(vector, pd.Series):
            return [_plain_python_value(value) for value in vector.tolist()]
        if isinstance(vector, pd.Index):
            return [_plain_python_value(value) for value in vector.tolist()]
        if isinstance(vector, (str, bytes)):
            return [vector]
        try:
            return [_plain_python_value(value) for value in list(vector)]
        except TypeError:
            return [_plain_python_value(vector)]


    def _plain_python_value(value):
        from datetime import date, datetime, time
        from decimal import Decimal

        import pandas as pd

        if hasattr(value, "py"):
            try:
                converted = value.py()
                if converted is not value:
                    value = converted
            except Exception:
                pass
        if hasattr(value, "tolist"):
            try:
                converted = value.tolist()
                if converted is not value:
                    value = converted
            except Exception:
                pass
        if hasattr(value, "item"):
            try:
                converted = value.item()
                if converted is not value:
                    value = converted
            except Exception:
                pass
        if isinstance(value, list):
            return [_plain_python_value(item) for item in value]
        if isinstance(value, tuple):
            return tuple(_plain_python_value(item) for item in value)
        if value is None or value is pd.NaT:
            return None
        if isinstance(value, (str, bytes, bool, int, float, Decimal, date, datetime, time)):
            return value
        # Do not let pandas see PyKX/foreign wrapper objects. Pandas may call
        # their __array__ implementation and recurse indefinitely.
        return str(value)


    ########################################################
    # src/databricks/labs/community_connector/sources/kx_kdb/kx_kdb.py
    ########################################################

    logger = logging.getLogger(__name__)


    class KxKdbLakeflowConnect(LakeflowConnect, SupportsPartitionedStream):
        """Read immutable KDB HDB date partitions through the Lakeflow connector APIs."""

        def __init__(self, options: dict[str, str]) -> None:
            options = self._with_table_config_defaults(options)
            super().__init__(options)
            self.hdb_root_path = self._required_absolute_path_option("hdb_root_path")
            self.license_path = self._required_absolute_path_option("license_volume_path")
            # Resolve any KDB-X bootstrap secrets on the driver so the resulting
            # runtime config can travel with the serialized connector object.
            self.runtime_config = build_runtime_config(self.options)
            self.license_path = self.runtime_config.license_directory
            self.discovery_sample_dates = self._int_option("discovery_sample_dates", 0)
            self._schema_cache: dict[tuple[str, str], StructType] = {}
            self._column_cache: dict[tuple[str, str], list[dict]] = {}
            self._table_dir_cache: dict[str, str] = {}
            self._partition_cache: dict[tuple[str, str | None, str | None], list[str]] = {}
            self._sym_cache: tuple[list[str], dict[str, int]] | None = None

        def _with_table_config_defaults(self, options: dict[str, str]) -> dict[str, str]:
            """Let pipeline tableConfigs override connection-level defaults."""
            raw_configs = options.get("tableConfigs")
            if not raw_configs:
                return options
            try:
                configs = json.loads(raw_configs)
            except Exception:
                return options
            if not isinstance(configs, dict):
                return options

            for config in configs.values():
                if isinstance(config, dict):
                    return {**options, **config}
            return options

        def list_tables(self) -> list[str]:
            return discover_tables(self.hdb_root_path, self.discovery_sample_dates)

        def get_table_schema(
            self, table_name: str, table_options: dict[str, str]
        ) -> StructType:
            cache_key = (table_name.lower(), self._ingestion_mode(table_options))
            if cache_key not in self._schema_cache:
                self._schema_cache[cache_key] = columns_to_spark_schema(
                    self._column_defs(table_name, table_options)
                )
            return self._schema_cache[cache_key]

        def read_table_metadata(
            self, table_name: str, table_options: dict[str, str]
        ) -> dict:
            self._actual_table_name(table_name)
            self._ingestion_mode(table_options)
            return {"primary_keys": None, "cursor_field": None, "ingestion_type": "append"}

        def read_table(
            self,
            table_name: str,
            start_offset: dict | None,
            table_options: dict[str, str],
        ) -> tuple[Iterator[dict], dict | None]:
            self._actual_table_name(table_name)
            partitions = self.get_partitions(table_name, table_options)
            records = chain.from_iterable(
                self.read_partition(table_name, partition, table_options)
                for partition in partitions
            )
            latest_partition = partitions[-1]["date_partition"] if partitions else None
            if latest_partition:
                return records, {"date_partition": latest_partition}
            return records, start_offset or {}

        def latest_offset(
            self,
            table_name: str,
            table_options: dict[str, str],
            start_offset: dict | None = None,
        ) -> dict:
            self._actual_table_name(table_name)
            partitions = self._available_partitions(table_name, table_options)
            if not partitions:
                return start_offset or {}
            return {"date_partition": partitions[-1]}

        def get_partitions(
            self,
            table_name: str,
            table_options: dict[str, str],
            start_offset: dict | None = None,
            end_offset: dict | None = None,
        ) -> Sequence[dict]:
            self._actual_table_name(table_name)
            available_partitions = self._available_partitions(table_name, table_options)

            if start_offset is None and end_offset is None:
                selected = available_partitions
            else:
                start_partition = normalize_partition_date(
                    (start_offset or {}).get("date_partition")
                )
                end_partition = normalize_partition_date((end_offset or {}).get("date_partition"))
                if not end_partition:
                    return []
                selected = [
                    partition
                    for partition in available_partitions
                    if (start_partition is None or partition > start_partition)
                    and partition <= end_partition
                ]

            strategy = self._partition_strategy(table_options)
            if not selected:
                logger.info(
                    "KX KDB partition plan table=%s strategy=%s selected_dates=0",
                    table_name,
                    strategy,
                )
                return []

            symbols, sym_indices = self._symbols_with_indices()
            descriptors = [
                {"date_partition": partition, "sym": symbol, "sym_index": sym_indices[symbol]}
                for partition in selected
                for symbol in symbols
                if symbol in sym_indices
            ]
            logger.info(
                "KX KDB partition plan table=%s strategy=%s dates=%s symbols=%s tasks=%s",
                table_name,
                strategy,
                len(selected),
                len(symbols),
                len(descriptors),
            )
            return descriptors

        def read_partition(
            self,
            table_name: str,
            partition: dict,
            table_options: dict[str, str],
        ) -> Iterator[dict]:
            date_partition = normalize_partition_date(partition.get("date_partition"))
            if not date_partition:
                return iter(())

            self._partition_strategy(table_options)
            if "sym_index" not in partition:
                raise ValueError(
                    "KX KDB date-only partition descriptors are not supported; "
                    "expected a date_sym descriptor with 'sym' and 'sym_index'."
                )

            actual_table_name = self._actual_table_name(table_name)
            return read_kdb_date_sym_records(
                hdb_root_path=self.hdb_root_path,
                kdb_table_name=actual_table_name,
                date_partition=date_partition,
                symbol=str(partition.get("sym", "")),
                sym_index=int(partition.get("sym_index", -1)),
                runtime_config=self.runtime_config,
                column_defs=self._column_defs(table_name, table_options),
                sym_column=self._sym_column(table_options),
                conversion_mode=self._partition_conversion_mode(table_options),
            )

        def _required_option(self, key: str) -> str:
            value = str(self.options.get(key, "")).strip()
            if not value:
                raise ValueError(f"KX KDB connector requires {key!r} in connection options")
            return value

        def _required_absolute_path_option(self, key: str) -> str:
            value = self._required_option(key)
            if not Path(value).is_absolute():
                raise ValueError(
                    f"KX KDB connector requires {key!r} to be an absolute filesystem path"
                )
            return value

        def _int_option(self, key: str, default: int) -> int:
            value = str(self.options.get(key, "")).strip()
            if not value:
                return default
            return int(value)

        def _ingestion_mode(self, table_options: dict[str, str]) -> str:
            mode = str(table_options.get("ingestion_mode", "append")).strip().lower()
            if mode != "append":
                raise ValueError(
                    f"Unsupported ingestion_mode {mode!r}. KX KDB supports append only."
                )
            return mode

        def _partition_strategy(self, table_options: dict[str, str]) -> str:
            strategy = str(table_options.get("partition_strategy", "date_sym")).strip().lower()
            if strategy != "date_sym":
                raise ValueError(
                    f"Unsupported partition_strategy {strategy!r}. KX KDB supports 'date_sym' only."
                )
            self._ingestion_mode(table_options)
            return strategy

        def _partition_conversion_mode(self, table_options: dict[str, str]) -> str:
            value = str(
                table_options.get(
                    "partition_conversion_mode", DEFAULT_PARTITION_CONVERSION_MODE
                )
            ).strip()
            return value or DEFAULT_PARTITION_CONVERSION_MODE

        def _sym_column(self, table_options: dict[str, str]) -> str:
            value = str(table_options.get("sym_column", "sym")).strip()
            if not value:
                raise ValueError("sym_column must be a non-empty KDB partition column name")
            return value

        def _symbols_with_indices(self) -> tuple[list[str], dict[str, int]]:
            if self._sym_cache is None:
                self._sym_cache = load_sym_enumeration_with_indices(
                    self.hdb_root_path,
                    self.runtime_config,
                )
            return self._sym_cache

        def _actual_table_name(self, table_name: str) -> str:
            cache_key = table_name.lower()
            if cache_key not in self._table_dir_cache:
                self._table_dir_cache[cache_key] = resolve_table_directory_name(
                    self.hdb_root_path,
                    table_name,
                    self.discovery_sample_dates,
                )
            return self._table_dir_cache[cache_key]

        def _available_partitions(
            self, table_name: str, table_options: dict[str, str]
        ) -> list[str]:
            start_date = normalize_partition_date(table_options.get("start_date"))
            end_date = normalize_partition_date(table_options.get("end_date"))
            cache_key = (table_name.lower(), start_date, end_date)
            if cache_key not in self._partition_cache:
                self._partition_cache[cache_key] = discover_table_partitions(
                    root_path=self.hdb_root_path,
                    table_name=table_name,
                    start_date=start_date,
                    end_date=end_date,
                )
            return self._partition_cache[cache_key]

        def _column_defs(self, table_name: str, table_options: dict[str, str]) -> list[dict]:
            cache_key = (table_name.lower(), self._ingestion_mode(table_options))
            if cache_key in self._column_cache:
                return self._column_cache[cache_key]

            partitions = self._available_partitions(table_name, table_options)
            if not partitions:
                raise RuntimeError(
                    f"No partitions found for table {table_name!r} under {self.hdb_root_path}"
                )

            columns = infer_schema_from_partition(
                hdb_root_path=self.hdb_root_path,
                kdb_table_name=self._actual_table_name(table_name),
                date_partition=partitions[0],
                runtime_config=self.runtime_config,
            )

            self._column_cache[cache_key] = columns
            return columns


